{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "In pigs, (R)-7 showed brain uptake above 2 SUV in cortex and thalamus after CsA pretreatment, demonstrating that this close analog can achieve meaningful brain levels despite being an efflux substrate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In rats, [11C]S14506 entered brain after IV administration, reaching 210% SUV at 2 min, directly demonstrating CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "In rats, [11C]6 showed low brain uptake and was excluded by the BBB; CsA pretreatment dramatically increased uptake, indicating poor baseline CNS access in this less-similar analog.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple direct in-vivo CNS exposure records in rats, pigs, and humans support meaningful brain penetration for close analogs; the clearest negative records come from less-similar efflux-substrate tracers. Overall evidence favors pass.",
  "evidence_gaps": [
    "Closest analog (C11) was measured after CsA pretreatment, so unmodified baseline brain uptake is not directly established.",
    "Negative analogs (C02, C10) are less similar and may not transfer to the query.",
    "Species, tracer, and dosing conditions vary across positive records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

